mapper.select:
SELECT fp.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, fp.FINPROD_NAME finprodName, fp.TRADE_MARKET tradeMarket, sdl3.item_value tradeMarketStr, fpa.ISSUERSHORT issueRshort, ci1.CUSTOMER_NAME issueRshortStr, nvl(fpa.NOM_CAPI,0)/10000 issueAmt, fpa.PROTECT_OBJECT protectObject, sdl4.item_value protectObjectStr, fpa.REF_SEC_FEATURES refSecFeatures, fpa.REF_SEC refSec, fpa.REF_ENTITY refEntityId, ci2.CUSTOMER_NAME refEntity, fp.MDATE mDate, fp.VDATE vDate, fpa.GRACE_PERIOD gracePeriod, fpa.BOOK_BUILDING_DATE pledgeDeadlineDate, fpa.PAY_DATE payDate, fpa.LISTING_DATE listingDate, fp.CALENDAR_ID calendarId, fp.ISSUE_PRICE issuePrice, fpa.SETTLE_METHOD settleMethod, sdl2.item_value settleMethodStr, fpa.IS_ALLOW_OVERWRITE isAllowOverwrite, sdl1.item_value isOrNoStr, fp.REMARK, fpa.BASIS ratebasic FROM FIN_PRODUCT fp LEFT JOIN FIN_PRODUCT_ADD fpa ON fp.FINPROD_ID = fpa.FINPROD_ID LEFT JOIN FIN_CASH_INFO fci ON fci.FINPROD_ID = fp.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO ci1 ON fpa.ISSUERSHORT = ci1.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO ci2 ON fpa.REF_ENTITY = ci2.CUSTOMER_ID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='YES_OR_NO' and sdl1.item_code = fpa.IS_ALLOW_OVERWRITE LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='SETTLE_METHOD' and sdl2.item_code = fpa.SETTLE_METHOD LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='TRADE_PLACE' and sdl3.item_code = fp.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='PROTECT_OBJECT' and sdl4.item_code = fpa.PROTECT_OBJECT
AND fp.FINPROD_TYPE2 = #{finprodType2}
AND (fp.FINPROD_MARKET_ID IN
#{item}
)
AND (fpa.REF_ENTITY IN
#{item}
)
AND (fpa.REF_SEC IN
#{item}
)
AND (fpa.ISSUERSHORT IN
#{item}
)
AND fp.vdate >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND fp.vdate <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND fp.mdate >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND fp.mdate <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
ORDER BY fp.FINPROD_ID

SELECT
T1.FINPROD_ABBR text
FROM FIN_PRODUCT T1

    AND T1.FINPROD_TYPE2 = #{finprodType2}
    AND T1.TRADE_MARKET in(#{TRADE_PLACE_03},#{TRADE_PLACE_04})

        AND (T1.FINPROD_MARKET_ID IN

            #{item}

        )

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

select sum(qty) from (
select count(1) as qty from ETR_ENTRUST where FINPROD_ID=#{finprodId}

    and ENTRUST_STATUS not in ('05','07') 

union all
select count(1) as qty from WFL_ETR_ENTRUST where FINPROD_ID=#{finprodId}
union all
select count(1) as qty from TRD_FIN_PRODUCT_DEAL_TOTAL t where t.FINPROD_ID=#{finprodId}

    and t.IS_CANCEL ='N' 


    and t.ps not in ('T41')

union all
select count(1) as qty from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID=#{finprodId}
)

SELECT
OUTPUT_VALUE_1 outputValue1,
OUTPUT_VALUE_2 outputValue2
FROM FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND INPUT_VALUE_2 = #{inputValue2}


    AND INPUT_VALUE_3 = #{inputValue3}
 and ROWNUM=1

select sum(num)
from (
         select count(ENTRUST_ID) as num
         from ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
           and ENTRUST_STATUS not in ('04', '06')
         union all
         select count(ENTRUST_ID) as num
         from WFL_ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
     )

sql.if:
AND  (
  sdl3.ITEM_VALUE like '%' || #{search} || '%'
  or sdl4.ITEM_VALUE like '%' || #{search} || '%'
  OR fp.FINPROD_ID like '%' || #{search} || '%'
  OR fp.FINPROD_MARKET_ID like '%' || #{search} || '%'
  OR fp.FINPROD_ABBR like '%' || #{search} || '%'
  OR fp.FINPROD_NAME like '%' || #{search} || '%'
  OR fpa.ISSUERSHORT like '%' || #{search} || '%'
  OR fpa.NOM_CAPI like '%' || #{search} || '%'
  OR fpa.PROTECT_OBJECT like '%' || #{search} || '%'
  OR fpa.REF_SEC_FEATURES like '%' || #{search} || '%'
  OR fpa.REF_SEC like '%' || #{search} || '%'
  OR fpa.REF_ENTITY like '%' || #{search} || '%'
  OR fpa.GRACE_PERIOD||'' = #{search}
  OR fp.CALENDAR_ID||'' like '%' || #{search} || '%'
  OR fp.ISSUE_PRICE||'' like '%' || #{search} || '%'
  OR fpa.BASIS||'' = #{search}
  OR sdl2.item_value||'' like '%' || #{search} || '%'
  OR TO_CHAR(fp.MDATE,'yyyy-MM-dd') ||''= #{search}
  OR TO_CHAR(fp.VDATE,'yyyy-MM-dd') ||''= #{search}
  OR TO_CHAR(fpa.PAY_DATE,'yyyy-MM-dd') ||''= #{search}
  OR TO_CHAR(fpa.LISTING_DATE,'yyyy-MM-dd') ||''= #{search}
  OR TO_CHAR(fpa.BOOK_BUILDING_DATE,'yyyy-MM-dd') ||''= #{search}
  )
